class Solution:
    def lengthOfLongestSubstring(self, s):
        last = {}
        left = ans = 0
        for i, c in enumerate(s):
            if c in last and last[c] >= left:
                left = last[c] + 1
            last[c] = i
            ans = max(ans, i - left + 1)
        return ans

