class Solution:
    def findMedianSortedArrays(self, a, b):
        if len(a) > len(b):
            a, b = b, a
        m, n = len(a), len(b)
        half = (m + n + 1) // 2
        l, r = 0, m
        INF = float("inf")
        while l <= r:
            i = (l + r) // 2
            j = half - i
            aL = a[i - 1] if i > 0 else -INF
            aR = a[i] if i < m else INF
            bL = b[j - 1] if j > 0 else -INF
            bR = b[j] if j < n else INF
            if aL <= bR and bL <= aR:
                if (m + n) & 1:
                    return float(max(aL, bL))
                return (max(aL, bL) + min(aR, bR)) / 2
            if aL > bR:
                r = i - 1
            else:
                l = i + 1
        return 0.0

