class Solution:
    def longestPalindrome(self, s):
        if not s:
            return ""

        def expand(l, r):
            while l >= 0 and r < len(s) and s[l] == s[r]:
                l -= 1
                r += 1
            return l + 1, r - 1

        bl, br = 0, 0
        for i in range(len(s)):
            for l0, r0 in (expand(i, i), expand(i, i + 1)):
                if r0 - l0 > br - bl:
                    bl, br = l0, r0
        return s[bl:br + 1]

