class Solution:
    def minWindow(self, s, t):
        if len(s) < len(t):
            return ""
        need = Counter(t)
        kinds = len(need)
        have = {}
        valid = 0
        l = 0
        best_l, best_len = 0, float("inf")
        for r, c in enumerate(s):
            if c in need:
                have[c] = have.get(c, 0) + 1
                if have[c] == need[c]:
                    valid += 1
            while valid == kinds:
                if r - l + 1 < best_len:
                    best_l, best_len = l, r - l + 1
                lc = s[l]
                if lc in need:
                    if have[lc] == need[lc]:
                        valid -= 1
                    have[lc] -= 1
                l += 1
        return "" if best_len == float("inf") else s[best_l:best_l + best_len]

